class Solution {
    public int largestCombination(int[] candidates){
        int answer=0;
        for(int bit=0;bit<31;bit++){
            int count=0;
            for(int value:candidates)if((value&(1<<bit))!=0)count++;
            answer=Math.max(answer,count);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun largestCombination(candidates:IntArray):Int{
        var answer=0;
        for(bit in 0 until 31)answer=maxOf(answer,candidates.count{
            it and (1 shl bit)!=0
        });
        return answer
    }
}

code.cpp:
class Solution {
    public:int largestCombination(vector<int>& candidates){
        int answer=0;
        for(int bit=0;bit<31;++bit){
            int count=0;
            for(int value:candidates)count+=value&(1<<bit)?1:0;
            answer=max(answer,count);
        }
        return answer;
    }
};
